			// Loop and create a sample of each font.			FontFamily[] ff = FontFamily.Families;			for (int x = 0; x < ff.Length; x++) {				Font font = null;				// Create the font - based on the styles available.				if (ff[x].IsStyleAvailable(FontStyle.Regular))					font = new Font(						ff[x].Name,						this.CbxFontName.Font.Size						);				else if (ff[x].IsStyleAvailable(FontStyle.Bold))					font = new Font(						ff[x].Name,						this.CbxFontName.Font.Size,						FontStyle.Bold						);				else if (ff[x].IsStyleAvailable(FontStyle.Italic))					font = new Font(						ff[x].Name,						this.CbxFontName.Font.Size,						FontStyle.Italic						);				else if (ff[x].IsStyleAvailable(FontStyle.Strikeout))					font = new Font(						ff[x].Name,						this.CbxFontName.Font.Size,						FontStyle.Strikeout						);				else if (ff[x].IsStyleAvailable(FontStyle.Underline))					font = new Font(						ff[x].Name,						this.CbxFontName.Font.Size,						FontStyle.Underline						);				// Should we add the item?				if (font != null) CbxFontName.Items.Add(font.FontFamily.Name);							}